/* One shared color source prevents mismatched sticker colors. */
var RouteeEditModel=(()=>{const palette=[['오렌지','#f8591f'],['라임','#e5ff4f'],['그린','#73efaf'],['민트','#63f6fd'],['퍼플','#ab9eff'],['핑크','#ffa3bc'],['화이트','#ffffff'],['네이비','#192031']];const types={record:{x:32,y:80,w:75,h:149.6,frame:{x:-17,y:-15,w:102,h:177}},timeline:{x:53,y:193,w:237.978,h:397,frame:{x:3,y:24,w:241,h:363}},route:{x:32,y:249.6,w:116,h:136,frame:{x:-11,y:-16.6,w:139,h:165}}};let sequence=0;function sticker(type,offset=0){const t=types[type];if(!t)throw Error('Unknown sticker');return{id:'edit-sticker-'+(++sequence),type,x:t.x+offset,y:t.y+offset,scale:1}}function create(){return{tab:null,color:'#63f6fd',dim:40,background:'assets/editor/imgImgLocation4.png',customBackground:false,stickers:[sticker('record'),sticker('timeline')],selected:null,dirty:false,stage:'edit'}}function tab(s,value){s.tab=value;s.selected=null}function color(s,value){if(!palette.some(p=>p[1]===value))return false;s.color=value;s.dirty=true;return true}function brightness(s,value){s.selected=null;s.dim=Math.max(0,Math.min(100,Number(value)||0));s.dirty=true}function add(s,type){const existing=s.stickers.find(x=>x.type===type);if(existing){s.selected=existing.id;s.tab='sticker';return existing}const item=sticker(type);s.stickers.push(item);s.selected=item.id;s.tab='sticker';s.dirty=true;return item}function remove(s,id){s.stickers=s.stickers.filter(x=>x.id!==id);if(s.selected===id)s.selected=null;s.dirty=true}function select(s,id){if(s.stage!=='edit'||!s.stickers.some(x=>x.id===id))return false;s.selected=id;return true}function transform(s,id,values){if(s.stage!=='edit')return false;const item=s.stickers.find(x=>x.id===id);if(!item)return false;for(const key of ['x','y','scale'])if(Number.isFinite(values[key]))item[key]=key==='scale'?Math.max(.01,values[key]):values[key];s.dirty=true;return true}return{palette,types,create,tab,color,brightness,add,remove,select,transform}})();
